app.get('/health',(_q,res)=>res.json({ok:true,version:'8.0.0',poolSize:questionPool.length,roundsPerGame:15,playerModes:[2,3,4],minCardsPerQuestion:4,selectionMode:'shuffle-bag',types:[...new Set(questionPool.map(q=>q.type))]}));
function cardCount(q){if(q.type==='choice')return q.options?.length||0;if(q.type==='order')return q.answers?.length||0;if(q.type==='category')return q.pairs?.length||0;return 0}
const invalidQuestions=questionPool.filter(q=>cardCount(q)<4);
if(invalidQuestions.length)throw new Error('Mindestens vier Karten erforderlich: '+invalidQuestions.map(q=>q.id).join(', '));
const rooms=new Map();
const roomCode=()=>Math.random().toString(36).slice(2,7).toUpperCase();
const cleanName=v=>String(v||'Spieler').trim().slice(0,20);
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function prep(q){q=JSON.parse(JSON.stringify(q));if(q.type==='choice')q.options=shuffle(q.options);if(q.type==='order')q.answers=shuffle(q.answers);if(q.type==='category')q.pairs=shuffle(q.pairs);return q}
let questionBag=[];
function refillQuestionBag(pool,excluded=new Set()){
  const eligible=pool.filter(q=>cardCount(q)>=4&&!excluded.has(q.id));
  questionBag.push(...shuffle(eligible.map(q=>q.id)));
}
function generateGame(pool,count=15){
  const selectedIds=[],selectedSet=new Set();
  while(selectedIds.length<count){
    if(questionBag.length===0)refillQuestionBag(pool,selectedSet);
    const id=questionBag.shift();
    if(!id||selectedSet.has(id))continue;
    selectedIds.push(id);selectedSet.add(id);
  }
  return selectedIds.map(id=>prep(pool.find(q=>q.id===id)));
}
function cards(q){return q.type==='choice'?q.options:q.type==='order'?q.answers:q.pairs.map(p=>p[0])}
function targets(q){return q.type==='choice'?[q.target]:q.type==='order'?q.labels:q.categories}
function needed(q){return q.type==='choice'?1:q.type==='order'?q.labels.length:q.pairs.length}
function validate(q,target,value,filled){if(q.type==='choice')return target===q.target&&value===q.correct?'answer':null;if(q.type==='order'){const i=Number(target),next=Object.keys(filled).length;return Number.isInteger(i)&&i===next&&q.originalAnswers[i]===value?String(i):null}return q.pairs.some(p=>p[0]===value&&p[1]===target)?value:null}
function createGame(host,maxPlayers=2){maxPlayers=[2,3,4].includes(Number(maxPlayers))?Number(maxPlayers):2;const rounds=generateGame(questionPool,15).map(q=>{if(q.type==='order'){q.originalAnswers=[...questionPool.find(x=>x.id===q.id).answers]}return q});return{players:[{id:host.id,name:cleanName(host.name),score:0,right:0,wrong:0,connected:true}],maxPlayers,activeRounds:rounds,round:0,turn:0,filled:{},status:'lobby',winners:[]}}
function state(code,g){const q=g.activeRounds[g.round]||g.activeRounds[g.activeRounds.length-1],used=new Set(Object.values(g.filled).map(v=>v.value));return{roomCode:code,players:g.players.map(p=>({name:p.name,score:p.score,right:p.right,wrong:p.wrong,connected:p.connected})),round:g.round,totalRounds:g.activeRounds.length,turn:g.turn,filled:g.filled,status:g.status,winners:g.winners,maxPlayers:g.maxPlayers,challenge:{id:q.id,title:`Aufgabe ${g.round+1}`,type:q.type,prompt:q.prompt,difficulty:q.difficulty,targets:targets(q),cards:cards(q).filter(c=>!used.has(c))}}}
const emit=c=>{const g=rooms.get(c);if(g)io.to(c).emit('state',state(c,g))},find=s=>[...s.rooms].find(r=>r!==s.id);
io.on('connection',socket=>{
socket.on('create-room',({name,maxPlayers=2}={},ack=()=>{})=>{let c;do c=roomCode();while(rooms.has(c));rooms.set(c,createGame({id:socket.id,name},maxPlayers));socket.join(c);socket.data.room=c;ack({ok:true,roomCode:c,playerIndex:0});emit(c)});
socket.on('join-room',({roomCode:c,name}={},ack=()=>{})=>{c=String(c||'').trim().toUpperCase();const g=rooms.get(c);if(!g)return ack({ok:false,message:'Raum nicht gefunden.'});if(g.players.length>=g.maxPlayers)return ack({ok:false,message:'Der Raum ist voll.'});g.players.push({id:socket.id,name:cleanName(name),score:0,right:0,wrong:0,connected:true});const playerIndex=g.players.length-1;g.status=g.players.length===g.maxPlayers?'playing':'lobby';socket.join(c);socket.data.room=c;ack({ok:true,roomCode:c,playerIndex});emit(c)});
socket.on('move',({target,value}={},ack=()=>{})=>{const c=find(socket),g=rooms.get(c);if(!g||g.status!=='playing')return ack({ok:false,message:'Spiel ist nicht aktiv.'});const pi=g.players.findIndex(p=>p.id===socket.id);if(pi!==g.turn)return ack({ok:false,message:'Du bist nicht am Zug.'});const q=g.activeRounds[g.round],key=validate(q,String(target),String(value),g.filled),correct=key!==null;if(correct){g.filled[key]={value:String(value),target:String(target),player:pi};g.players[pi].score+=10;g.players[pi].right++}else{g.players[pi].score=Math.max(0,g.players[pi].score-5);g.players[pi].wrong++}g.turn=(g.turn+1)%g.players.length;if(correct&&Object.keys(g.filled).length===needed(q)){g.round++;g.filled={};if(g.round>=g.activeRounds.length){g.status='finished';const bestScore=Math.max(...g.players.map(p=>p.score));const leaders=g.players.map((p,i)=>({p,i})).filter(x=>x.p.score===bestScore);const minWrong=Math.min(...leaders.map(x=>x.p.wrong));g.winners=leaders.filter(x=>x.p.wrong===minWrong).map(x=>x.i)}}ack({ok:true,correct});emit(c)});
socket.on('restart',()=>{const c=find(socket),g=rooms.get(c);if(!g||g.players[0]?.id!==socket.id)return;const ng=createGame({id:g.players[0].id,name:g.players[0].name},g.maxPlayers);ng.players=g.players.map(p=>({...p,score:0,right:0,wrong:0}));ng.status=ng.players.length===ng.maxPlayers?'playing':'lobby';rooms.set(c,ng);emit(c)});
socket.on('disconnect',()=>{const c=socket.data.room,g=rooms.get(c);if(!g)return;const p=g.players.find(p=>p.id===socket.id);if(p)p.connected=false;io.to(c).emit('peer-left',{message:'Der andere Spieler hat die Verbindung getrennt.'});emit(c)});
});
server.listen(process.env.PORT||3000,()=>console.log('Netzwerk-Duell v8.0: 250 Aufgaben, faire Shuffle-Bag-Auswahl, 2-4 Spieler.'));
